window.PM_DATA=window.PM_DATA||{};PM_DATA.places={"landmarks":[{"name":"Empire State Building","x":500.5,"y":930.6,"lat":40.748442,"lon":-73.985659,"fact":"Built in just 410 days in 1930-31.","about":"The Empire State Building is a 102-story, supertall skyscraper in the Midtown South neighborhood of Manhattan, New York City, United States. The building was designed in the Art Deco style by Shreve, Lamb & Harmon and constructed between 1930 and 1931.","wiki":"https://en.wikipedia.org/wiki/Empire_State_Building","img":"data:image/jpeg;base64,","credit":"Sam Valadi Public domain","file":"https://commons.wikimedia.org/wiki/File:Empire_State_Building_(aerial_view).jpg"},{"name":"Times Square","x":-10.0,"y":-55.7,"lat":40.758485,"lon":-73.985284,"fact":"Named for The New York Times, which moved here in 1904.","about":"Times Square is one of the world's busiest pedestrian intersections, tourist destinations, and entertainment hubs. It is formed by the junction of Broadway, Seventh Avenue, and 42nd Street in Midtown Manhattan, New York City.","wiki":"https://en.wikipedia.org/wiki/Times_Square","img":"data:image/jpeg;base64,","credit":"Terabass CC BY-SA 3.0","file":"https://commons.wikimedia.org/wiki/File:New_york_times_square-terabass.jpg"},{"name":"Grand Central Terminal","x":893.4,"y":181.2,"lat":40.752648,"lon":-73.977275,"fact":"Its ceiling shows the zodiac painted backwards.","about":"Grand Central Terminal (GCT; also referred to as Grand Central Station or simply as Grand Central) is a commuter rail terminal at 42nd Street and Park Avenue in Midtown Manhattan, New York City.","wiki":"https://en.wikipedia.org/wiki/Grand_Central_Terminal","img":"data:image/jpeg;base64,","credit":"Fcb981 ; Eric Baetscher (attribution required) CC BY-SA 3.0","file":"https://commons.wikimedia.org/wiki/File:Image-Grand_central_Station_Outside_Night_2.jpg"},{"name":"Rockefeller Center","x":448.8,"y":-355.5,"lat":40.758845,"lon":-73.978801,"fact":"Its Christmas tree tradition began in 1931.","about":"Rockefeller Center is a complex of 19 commercial buildings covering 22 acres (8.9 ha) between 48th Street and 51st Street in the Midtown Manhattan neighborhood of New York City.","wiki":"https://en.wikipedia.org/wiki/Rockefeller_Center","img":"data:image/jpeg;base64,","credit":"Wikimedia Commons","file":"https://commons.wikimedia.org/wiki/File:330px-Rockefeller_Center_logo.svg.png%3Futm_source%3Den.wikipedia.org%26utm_campaign%3Dapi%26utm_content%3Dthumbnail"},{"name":"Flatiron Building","x":600.7,"y":1811.8,"lat":40.74103,"lon":-73.989686,"fact":"Its triangle shape follows the angle of Broadway.","about":"The Flatiron Building (originally the Fuller Building) is a 22-story, 307-foot-tall (93.6 m) steel-framed triangular building at 175 Fifth Avenue in the Flatiron District neighborhood of Manhattan in New York City, New York, US. Designed by Daniel Burnham and Frederick P.","wiki":"https://en.wikipedia.org/wiki/Flatiron_Building","img":"data:image/jpeg;base64,","credit":"Imelenchon (original work) Public domain","file":"https://commons.wikimedia.org/wiki/File:Edificio_Fuller_(Flatiron)_en_2010_desde_el_Empire_State_crop_boxin.jpg"},{"name":"Chrysler Building","x":1091.2,"y":201.3,"lat":40.751622,"lon":-73.975339,"fact":"Its spire was assembled in secret inside the building.","about":"The Chrysler Building is a 1,046-foot-tall (319 m), Art Deco skyscraper in the East Midtown neighborhood of Manhattan, New York City, United States. Located at the intersection of 42nd Street and Lexington Avenue, it is the tallest steel-framed brick building in the world.","wiki":"https://en.wikipedia.org/wiki/Chrysler_Building"},{"name":"One World Trade Center","x":369.5,"y":5482.6,"lat":40.712999,"lon":-74.013189,"fact":"It stands 1,776 feet tall, for 1776.","about":"One World Trade Center, also known as One WTC and the Freedom Tower, is the main building of the rebuilt World Trade Center complex in Lower Manhattan, New York City.","wiki":"https://en.wikipedia.org/wiki/One_World_Trade_Center","img":"data:image/jpeg;base64,","credit":"Wikimedia Commons","file":"https://commons.wikimedia.org/wiki/File:120px-One_WTC_logo.svg.png%3Futm_source%3Den.wikipedia.org%26utm_campaign%3Dapi%26utm_content%3Dthumbnail"},{"name":"Charging Bull","x":749.1,"y":6212.0,"lat":40.705564,"lon":-74.013446,"fact":"Dropped off unannounced by artist Arturo Di Modica in 1989.","about":"Charging Bull (sometimes referred to as the Bull of Wall Street or the Bowling Green Bull) is a bronze sculpture that stands on Broadway just north of Bowling Green in the Financial District of Manhattan in New York City.","wiki":"https://en.wikipedia.org/wiki/Charging_Bull"},{"name":"Brooklyn Bridge","x":1147.0,"y":5243.7,"lat":40.71148,"lon":-74.003752,"fact":"Opened in 1883, it was the world's first steel-wire suspension bridge.","about":"The Brooklyn Bridge is a cable-stayed suspension bridge in New York City, spanning the East River between the boroughs of Manhattan and Brooklyn. Opened on May 24, 1883, the Brooklyn Bridge was the first fixed crossing of the East River.","wiki":"https://en.wikipedia.org/wiki/Brooklyn_Bridge","img":"data:image/jpeg;base64,","credit":"Christian David CC BY-SA 4.0","file":"https://commons.wikimedia.org/wiki/File:Brooklyn_Bridge_and_the_Lower_Manhattan_skyline_from_Pebble_Beach,_New_York.jpg"},{"name":"City Hall","x":868.9,"y":5251.4,"lat":40.712639,"lon":-74.006681,"fact":"The oldest US city hall still used for its original purpose.","about":"New York City Hall is the seat of New York City government, located at the center of City Hall Park in the Civic Center area of Lower Manhattan, between Broadway, Park Row, and Chambers Street.","wiki":"https://en.wikipedia.org/wiki/New_York_City_Hall","img":"data:image/jpeg;base64,","credit":"MusikAnimal CC BY-SA 4.0","file":"https://commons.wikimedia.org/wiki/File:New_York_City_Hall_exterior,_October_2016.jpg"},{"name":"Washington Square Arch","x":578.7,"y":3062.0,"lat":40.731235,"lon":-73.997102,"fact":"Built for the centennial of George Washington's inauguration.","about":"The Washington Square Arch, officially the Washington Arch, is a marble memorial arch at the Washington Square Park, at Greenwich Village neighborhood of Lower Manhattan, New York City, United States.","wiki":"https://en.wikipedia.org/wiki/Washington_Square_Arch","img":"data:image/jpeg;base64,","credit":"Nan Palmero from San Antonio, TX, USA CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:Washington_Square_Arch_(40430304445).jpg"},{"name":"Union Square","x":813.5,"y":2300.0,"lat":40.736234,"lon":-73.990286,"fact":"Home to the city's best-known farmers market.","about":"Union Square is a historic intersection and surrounding neighborhood in Manhattan, New York City, United States, located where Broadway and the former Bowery Road – now Park Avenue north of the Square – came together in the early 19th century.","wiki":"https://en.wikipedia.org/wiki/Union_Square,_Manhattan","img":"data:image/jpeg;base64,","credit":"chensiyuan CC BY-SA 4.0","file":"https://commons.wikimedia.org/wiki/File:1_new_york_city_union_square_2010.JPG"},{"name":"Madison Square Garden","x":-189.5,"y":1050.6,"lat":40.750518,"lon":-73.993506,"fact":"The fourth arena to carry the name, sitting atop Penn Station.","about":"Madison Square Garden, colloquially known as the Garden or by its initials MSG, is a multi-purpose indoor arena in Midtown Manhattan, New York City, U.S. The arena is located between Seventh and Eighth avenues, extending from 31st to 33rd streets, atop Pennsylvania Station.","wiki":"https://en.wikipedia.org/wiki/Madison_Square_Garden","img":"data:image/jpeg;base64,","credit":"Ajay Suresh from New York, NY, USA CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:Madison_Square_Garden_(MSG)_-_Full_(48124330357).jpg"},{"name":"Bethesda Terrace","x":210.8,"y":-2166.2,"lat":40.774215,"lon":-73.970859,"fact":"Its Angel of the Waters was the first public statue in NYC by a woman.","about":"Bethesda Terrace and Fountain are two architectural features overlooking the southern shore of the Lake in New York City's Central Park. The fountain, with its Angel of the Waters statue, is located in the center of the terrace.","wiki":"https://en.wikipedia.org/wiki/Bethesda_Terrace_and_Fountain","img":"data:image/jpeg;base64,","credit":"Julian Lupyan CC0","file":"https://commons.wikimedia.org/wiki/File:Bethesda_Terrace_and_Fountain,_Central_Park,_2025.jpg"},{"name":"Columbus Circle","x":-274.8,"y":-1123.5,"lat":40.768094,"lon":-73.981891,"fact":"The point from which all official NYC distances are measured.","about":"Columbus Circle is a traffic circle and busy road junction in the New York City borough of Manhattan, at the intersection of Eighth Avenue, Broadway, Central Park South (West 59th Street), and Central Park West, at the southwest corner of Central Park.","wiki":"https://en.wikipedia.org/wiki/Columbus_Circle","img":"data:image/jpeg;base64,","credit":"TarHeel4793 CC BY-SA 4.0","file":"https://commons.wikimedia.org/wiki/File:Columbus_Circle_in_New_York_City.jpg"},{"name":"Lincoln Center","x":-689.9,"y":-1473.2,"lat":40.772682,"lon":-73.984185,"fact":"Built on land cleared from the old San Juan Hill neighborhood.","about":"Lincoln Center for the Performing Arts (also simply known as Lincoln Center) is a 16.3-acre (6.6-hectare) complex of buildings in the Lincoln Square neighborhood on the Upper West Side of Manhattan. It has thirty indoor and outdoor facilities and is host to five million visitors annually.","wiki":"https://en.wikipedia.org/wiki/Lincoln_Center","img":"data:image/jpeg;base64,","credit":"Ajay Suresh from New York, NY, USA CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:Lincoln_Center_Overview_(48047495362).jpg"},{"name":"United Nations Headquarters","x":1773.9,"y":78.3,"lat":40.749601,"lon":-73.967551,"fact":"The site is international territory.","about":"The headquarters of the United Nations (UN) is on 17 to 18 acres (6.9 to 7.3 ha) of grounds in the Turtle Bay neighborhood of Midtown Manhattan in New York City, United States. It borders First Avenue to the west, 42nd Street to the south, 48th Street to the north, and the East River to the east.","wiki":"https://en.wikipedia.org/wiki/Headquarters_of_the_United_Nations","img":"data:image/jpeg;base64,","credit":"Kidfly182 CC BY-SA 4.0","file":"https://commons.wikimedia.org/wiki/File:Midtown_Manhattan_Skyline_004_(cropped).jpg"},{"name":"St. Patrick's Cathedral","x":673.8,"y":-436.7,"lat":40.7585,"lon":-73.976,"fact":"The largest Gothic Revival Catholic cathedral in North America.","about":"St. Patrick's Cathedral is a Catholic cathedral in the Midtown Manhattan neighborhood of New York City, United States.","wiki":"https://en.wikipedia.org/wiki/St._Patrick%27s_Cathedral_(New_York_City)","img":"data:image/jpeg;base64,","credit":"Ajay Suresh CC BY 4.0","file":"https://commons.wikimedia.org/wiki/File:St._Patrick%27s_Cathedral_-_2026_(55284018525).jpg"},{"name":"Apollo Theater","x":-165.4,"y":-6496.7,"lat":40.810129,"lon":-73.949863,"fact":"Amateur Night has launched careers since 1934.","about":"The Apollo Theater (formerly the Hurtig & Seamon's New Theatre; also Apollo Theatre or 125th Street Apollo Theatre) is a multi-use theater at 253 West 125th Street in the Harlem neighborhood of Upper Manhattan in New York City.","wiki":"https://en.wikipedia.org/wiki/Apollo_Theater","img":"data:image/jpeg;base64,","credit":"Ajay Suresh from New York, NY, USA CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:Harlem_-_Apollo_Theater_(48555309512).jpg"},{"name":"Low Memorial Library","x":-946.3,"y":-5823.1,"lat":40.808224,"lon":-73.961835,"fact":"The domed centerpiece of Columbia University.","about":"The Low Memorial Library (nicknamed Low) is a building at the center of Columbia University's campus in Upper Manhattan, New York City, U.S. The building, located near 116th Street between Broadway and Amsterdam Avenue, was designed by Charles Follen McKim of the firm McKim, Mead & White.","wiki":"https://en.wikipedia.org/wiki/Low_Memorial_Library","img":"data:image/jpeg;base64,","credit":"Ajay Suresh from New York, NY, USA CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:Columbia_University_-_Low_Memorial_Library_(48170370506).jpg"},{"name":"Cathedral of St. John the Divine","x":-714.0,"y":-5392.7,"lat":40.8038,"lon":-73.9619,"fact":"Under construction since 1892 and still unfinished.","about":"The Cathedral of St. John the Divine (sometimes referred to as St.","wiki":"https://en.wikipedia.org/wiki/Cathedral_of_St._John_the_Divine","img":"data:image/jpeg;base64,","credit":"ajay_suresh CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:Cathedral_of_St._John_the_Divine_(52009407636).jpg"},{"name":"Grant's Tomb","x":-1309.6,"y":-6275.9,"lat":40.8134,"lon":-73.963,"fact":"The largest mausoleum in North America.","about":"Grant's Tomb, officially the General Grant National Memorial, is the final resting place of Ulysses S. Grant, the 18th president of the United States, and of his wife Julia.","wiki":"https://en.wikipedia.org/wiki/Grant%27s_Tomb","img":"data:image/jpeg;base64,","credit":"King of Hearts CC BY-SA 4.0","file":"https://commons.wikimedia.org/wiki/File:General_Grant_National_Memorial_New_York_November_2016_003.jpg"},{"name":"Little Red Lighthouse","x":-2101.9,"y":-10494.7,"lat":40.850255,"lon":-73.946963,"fact":"Saved from demolition by a 1942 children's book.","about":"The Little Red Lighthouse, officially Jeffrey's Hook Light, is a small lighthouse located in Fort Washington Park along the Hudson River in Manhattan, New York City, under the George Washington Bridge.","wiki":"https://en.wikipedia.org/wiki/Little_Red_Lighthouse","img":"data:image/jpeg;base64,","credit":"Billie Grace Ward CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:Little_Red_Lighthouse,_Fort_Washington_Park.jpg"},{"name":"George Washington Bridge","x":-2648.4,"y":-10392.0,"lat":40.851839,"lon":-73.953222,"fact":"One of the world's busiest motor-vehicle bridges.","about":"The George Washington Bridge is a double-decked suspension bridge spanning the Hudson River, connecting Fort Lee in Bergen County, New Jersey, with the Washington Heights neighborhood of Manhattan, New York City.","wiki":"https://en.wikipedia.org/wiki/George_Washington_Bridge","img":"data:image/jpeg;base64,","credit":"Hudconja CC BY-SA 3.0","file":"https://commons.wikimedia.org/wiki/File:GWBfromFortLeeHistoricPark.JPG"},{"name":"Hamilton Grange","x":-594.6,"y":-7713.9,"lat":40.821643,"lon":-73.947316,"fact":"Alexander Hamilton's only home, moved twice.","about":"Hamilton Grange National Memorial (also known as Hamilton Grange or the Grange) is a historic house museum within St. Nicholas Park in the Hamilton Heights neighborhood of Manhattan in New York City, United States.","wiki":"https://en.wikipedia.org/wiki/Hamilton_Grange_National_Memorial","img":"data:image/jpeg;base64,","credit":"Ajay Suresh from New York, NY, USA CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:Hamilton_Grange_National_Memorial_-_Entrance_(48170424452).jpg"},{"name":"Morris-Jumel Mansion","x":-637.6,"y":-9311.1,"lat":40.834468,"lon":-73.93858,"fact":"Manhattan's oldest house, Washington's HQ in 1776.","about":"The Morris–Jumel Mansion (also known as the Morris House, Mount Morris, Jumel Mansion, and Morris–Jumel Mansion Museum) is an 18th-century historic house museum in the Washington Heights neighborhood of Upper Manhattan in New York City, United States.","wiki":"https://en.wikipedia.org/wiki/Morris%E2%80%93Jumel_Mansion","img":"data:image/jpeg;base64,","credit":"Beyond My Ken CC BY-SA 4.0","file":"https://commons.wikimedia.org/wiki/File:2014_Morris-Jumel_Mansion_from_southwest.jpg"},{"name":"The Vessel","x":-1081.0,"y":1094.3,"lat":40.754083,"lon":-74.003004,"fact":"A honeycomb of 154 flights of stairs at Hudson Yards.","about":"Vessel is a 16-story, 150-foot-tall (46 m) structure of connected staircases in the 5-acre (2.0 ha) Hudson Yards Public Square of Hudson Yards in Manhattan, New York City.","wiki":"https://en.wikipedia.org/wiki/Vessel_(structure)","img":"data:image/jpeg;base64,","credit":"Epicgenius CC BY-SA 4.0","file":"https://commons.wikimedia.org/wiki/File:Hudson_Yards_Plaza_March_2019_53.jpg"},{"name":"Stonewall Inn","x":67.3,"y":3019.2,"lat":40.733816,"lon":-74.002161,"fact":"The first US national monument to LGBTQ+ rights.","about":"The Stonewall Inn (also known as Stonewall) is a gay bar and recreational tavern at 53 Christopher Street in the Greenwich Village neighborhood of Lower Manhattan in New York City.","wiki":"https://en.wikipedia.org/wiki/Stonewall_Inn","img":"data:image/jpeg;base64,","credit":"Rhododendrites CC BY-SA 4.0","file":"https://commons.wikimedia.org/wiki/File:Stonewall_Inn_5_pride_weekend_2016.jpg"},{"name":"Williamsburg Bridge","x":2231.4,"y":3905.8,"lat":40.71731,"lon":-73.984811,"fact":"It was the longest suspension bridge in the world when it opened in 1903.","about":"The Williamsburg Bridge is a suspension bridge across the East River in New York City, connecting the Lower East Side of Manhattan with the Williamsburg neighborhood of Brooklyn. Originally known as the East River Bridge, the Williamsburg Bridge was completed in 1903.","wiki":"https://en.wikipedia.org/wiki/Williamsburg_Bridge","img":"data:image/jpeg;base64,","credit":"Praneeth Thalla CC BY-SA 4.0","file":"https://commons.wikimedia.org/wiki/File:Williamsburg_Bridge_full.jpg"},{"name":"Manhattan Bridge Arch","x":1561.8,"y":4512.7,"lat":40.715445,"lon":-73.995246,"fact":"Its grand entrance was modeled on the Porte Saint-Denis in Paris.","about":"The Manhattan Bridge is a suspension bridge that crosses the East River in New York City, connecting Lower Manhattan at Canal Street with Downtown Brooklyn at the Flatbush Avenue Extension. Designed by Leon Moisseiff, the bridge has a total length of 6,855 ft (2,089 m).","wiki":"https://en.wikipedia.org/wiki/Manhattan_Bridge","img":"data:image/jpeg;base64,","credit":"Kidfly182 CC BY-SA 4.0","file":"https://commons.wikimedia.org/wiki/File:Manhattan_Bridge_January_2023_003.jpg"},{"name":"Old St. Patrick's Cathedral","x":1120.8,"y":3726.4,"lat":40.7236,"lon":-73.9953,"fact":"The city's first Catholic cathedral, dedicated in 1815."},{"name":"South Street Seaport","x":1516.4,"y":5763.0,"lat":40.705751,"lon":-74.002906,"fact":"The old port where the city's shipping trade grew up.","about":"The South Street Seaport is a historic area and neighborhood in the New York City borough of Manhattan, centered where Fulton Street meets the East River, within the Financial District of Lower Manhattan. The Seaport is a designated historic district.","wiki":"https://en.wikipedia.org/wiki/South_Street_Seaport","img":"data:image/jpeg;base64,","credit":"Unknown authorUnknown author Public domain","file":"https://commons.wikimedia.org/wiki/File:South_Street_Seaport,_Detroit_Photographic_Company_(0616).jpg"},{"name":"Staten Island Ferry Terminal","x":1003.1,"y":6610.1,"lat":40.7013,"lon":-74.0131,"fact":"The ferry is free and carries about 45,000 people a day.","about":"The Whitehall Terminal is a ferry terminal in the South Ferry section of Lower Manhattan, New York City, at the corner of South Street and Whitehall Street. It is used by the Staten Island Ferry, which connects the island boroughs of Manhattan and Staten Island.","wiki":"https://en.wikipedia.org/wiki/Staten_Island_Ferry_Whitehall_Terminal","img":"data:image/jpeg;base64,","credit":"Ajay Suresh from New York, NY, USA CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:Staten_Island_Ferry_Whitehall_Terminal_(48126534661).jpg"},{"name":"Astor Place Cube","x":1084.2,"y":2912.6,"lat":40.7302,"lon":-73.991,"fact":"The 'Alamo' sculpture spins if you push hard enough.","about":"Alamo, also known as the Astor Place Cube or simply The Cube, is an outdoor sculpture by Tony Rosenthal, located on Astor Place, in the East Village neighborhood of Manhattan in New York City. It is a black cube, 8 feet (2.4 m) long on each side, mounted on a corner.","wiki":"https://en.wikipedia.org/wiki/Alamo_(sculpture)","img":"data:image/jpeg;base64,","credit":"Beyond My Ken Public domain","file":"https://commons.wikimedia.org/wiki/File:Just_another_Alamo_afternoon.jpg"},{"name":"Gramercy Park","x":1157.5,"y":2023.9,"lat":40.73691,"lon":-73.98513,"fact":"Manhattan's only private park; residents hold keys.","about":"Gramercy Park () is the name of both a small, fenced-in private park, and the surrounding neighborhood (which is also referred to as Gramercy), in Manhattan in New York City.","wiki":"https://en.wikipedia.org/wiki/Gramercy_Park","img":"data:image/jpeg;base64,","credit":"Dmadeo CC BY-SA 3.0","file":"https://commons.wikimedia.org/wiki/File:Gramercy-park-2007.jpg"},{"name":"Gracie Mansion","x":2158.4,"y":-3485.6,"lat":40.776113,"lon":-73.943071,"fact":"The official residence of the Mayor since 1942.","about":"Gracie Mansion (also known as Archibald Gracie Mansion) is the official residence of the mayor of New York City. Built in 1799, it is located in Carl Schurz Park, at East End Avenue and 88th Street in the Yorkville neighborhood of Manhattan.","wiki":"https://en.wikipedia.org/wiki/Gracie_Mansion","img":"data:image/jpeg;base64,","credit":"Jim.henderson CC0","file":"https://commons.wikimedia.org/wiki/File:Gracie_Mansion_snow_jeh.jpg"},{"name":"Roosevelt Island Tramway","x":1397.4,"y":-1179.7,"lat":40.761205,"lon":-73.964223,"fact":"One of the few commuter aerial tramways in North America.","about":"The Roosevelt Island Tramway is an aerial tramway that crosses the East River in New York City, connecting Roosevelt Island to the Upper East Side of Manhattan.","wiki":"https://en.wikipedia.org/wiki/Roosevelt_Island_Tramway","img":"data:image/jpeg;base64,","credit":"Autopilot CC BY-SA 3.0","file":"https://commons.wikimedia.org/wiki/File:Roosevelt_Island_tramcar_2010.jpg"},{"name":"Carnegie Hall","x":37.1,"y":-905.0,"lat":40.764998,"lon":-73.979912,"fact":"Tchaikovsky conducted on opening night in 1891.","about":"Carnegie Hall ( KAR-nig-ee) is a concert venue at 881 Seventh Avenue, between 56th and 57th Streets, in Midtown Manhattan, New York City.","wiki":"https://en.wikipedia.org/wiki/Carnegie_Hall","img":"data:image/jpeg;base64,","credit":"Ajay Suresh from New York, NY, USA CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:Carnegie_Hall_-_Full_(48155558466).jpg"},{"name":"Javits Center","x":-1215.5,"y":711.7,"lat":40.7577,"lon":-74.0022,"fact":"Its green roof is home to thousands of birds and bees.","about":"The Jacob K. Javits Convention Center, commonly known as the Javits Center, is a large convention center on Eleventh Avenue between 34th Street and 38th Street in Hell's Kitchen, Manhattan, New York City.","wiki":"https://en.wikipedia.org/wiki/Javits_Center","img":"data:image/jpeg;base64,","credit":"Ajay Suresh from New York, NY, USA CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:Javits_Center_-_Full_Front_(49052081016).jpg"},{"name":"The Dakota","x":-317.0,"y":-2197.4,"lat":40.776777,"lon":-73.976154,"fact":"Named because it once seemed as remote as the Dakota Territory.","about":"The Dakota, also known as the Dakota Apartments, is a cooperative apartment building at 1 West 72nd Street on the Upper West Side of Manhattan in New York City, New York, US.","wiki":"https://en.wikipedia.org/wiki/The_Dakota","img":"data:image/jpeg;base64,","credit":"Ajay Suresh from New York, NY, USA CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:The_Dakota_(48269594271).jpg"},{"name":"Dyckman Farmhouse","x":-1130.1,"y":-13187.6,"lat":40.8673,"lon":-73.9214,"fact":"Manhattan's last remaining Dutch colonial farmhouse.","about":"The Dyckman House, now the Dyckman Farmhouse Museum, is the oldest remaining farmhouse on Manhattan island, a vestige of New York City's rural past.","wiki":"https://en.wikipedia.org/wiki/Dyckman_House","img":"data:image/jpeg;base64,","credit":"Jim.henderson CC0","file":"https://commons.wikimedia.org/wiki/File:Dyckman_House_Bwy_cloudy_jeh_crop.jpg"},{"name":"Strawberry Fields","x":-202.9,"y":-2142.8,"lat":40.775844,"lon":-73.975285,"fact":"Its 'Imagine' mosaic honors John Lennon.","about":"Strawberry Fields is a 2.5-acre (1.0 ha) landscaped section in New York City's Central Park, designed by the landscape architect Bruce Kelly, that is dedicated to the memory of former Beatles member John Lennon. It is named after the Beatles' song \"Strawberry Fields Forever\", written by Lennon.","wiki":"https://en.wikipedia.org/wiki/Strawberry_Fields_(memorial)","img":"data:image/jpeg;base64,","credit":"Ingfbruno CC BY-SA 3.0","file":"https://commons.wikimedia.org/wiki/File:2960-Central_Park-Strawberry_Fields.JPG"},{"name":"Belvedere Castle","x":82.1,"y":-2740.3,"lat":40.779322,"lon":-73.968893,"fact":"A 'folly' built as a lookout, now a weather station.","about":"Belvedere Castle is a folly in Central Park in Manhattan, New York City. It contains exhibit rooms, an observation deck, and since 1919 has housed Central Park’s official weather station.","wiki":"https://en.wikipedia.org/wiki/Belvedere_Castle","img":"data:image/jpeg;base64,","credit":"Christian David CC BY-SA 4.0","file":"https://commons.wikimedia.org/wiki/File:Belvedere_Castle_and_Turtle_Pond,_Central_Park,_Manhattan,_New_York.jpg"},{"name":"The Plaza Hotel","x":464.9,"y":-1091.9,"lat":40.7646,"lon":-73.9744,"fact":"Home of Eloise, the girl who lived on the top floor.","about":"The Plaza Hotel (also known as The Plaza) is a luxury hotel and condominium apartment building in Midtown Manhattan in New York City.","wiki":"https://en.wikipedia.org/wiki/Plaza_Hotel"},{"name":"Port Authority Bus Terminal","x":-397.8,"y":362.0,"lat":40.756881,"lon":-73.991708,"fact":"The busiest bus terminal in the world.","about":"The Port Authority Bus Terminal (colloquially known as the Port Authority and by its acronym PABT) is a bus terminal located in Manhattan in New York City.","wiki":"https://en.wikipedia.org/wiki/Port_Authority_Bus_Terminal","img":"data:image/jpeg;base64,","credit":"ajay_suresh CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:Port_Authority_Bus_Terminal_(48295955196).jpg"},{"name":"Harlem Meer","x":410.0,"y":-5055.5,"lat":40.796202,"lon":-73.952181,"fact":"Meer is Dutch for lake.","about":"Harlem Meer is a man-made lake at the northeast corner of New York City's Central Park. It lies west of Fifth Avenue, south of 110th Street, and north of the Conservatory Garden, near the Harlem and East Harlem neighborhoods of Manhattan.","wiki":"https://en.wikipedia.org/wiki/Harlem_Meer","img":"data:image/jpeg;base64,","credit":"King of Hearts CC BY-SA 4.0","file":"https://commons.wikimedia.org/wiki/File:Central_Park_New_York_October_2016_panorama_1.jpg"},{"name":"Audubon Ballroom","x":-985.2,"y":-9830.2,"lat":40.8401,"lon":-73.9392,"fact":"Where Malcolm X was assassinated in 1965.","about":"The Audubon Theatre and Ballroom (generally referred to as the Audubon Ballroom) was a theatre and ballroom located at 3940 Broadway, at the intersection with West 165th Street, in the Washington Heights neighborhood of Manhattan, New York City. It was built in 1912 and was designed by Thomas W.","wiki":"https://en.wikipedia.org/wiki/Audubon_Ballroom","img":"data:image/jpeg;base64,","credit":"Beyond My Ken CC BY-SA 4.0","file":"https://commons.wikimedia.org/wiki/File:2014_Audubon_Ballroom_and_Lasker_Biomedical_Research_Building.jpg"},{"name":"Shepard Hall","x":-606.9,"y":-7565.6,"lat":40.820522,"lon":-73.948296,"fact":"City College's Gothic hall, clad in Manhattan schist."},{"name":"Ghostbusters Firehouse","x":496.4,"y":4565.4,"lat":40.7197,"lon":-74.0066,"fact":"Hook & Ladder 8 played the Ghostbusters' HQ in 1984."},{"name":"Hotel Chelsea","x":-104.4,"y":1780.0,"lat":40.744374,"lon":-73.996818,"fact":"Home over the years to Twain, Warhol, and Patti Smith.","about":"The Hotel Chelsea (also known as the Chelsea Hotel and the Chelsea) is a hotel at 222 West 23rd Street in the Chelsea neighborhood of Manhattan in New York City.","wiki":"https://en.wikipedia.org/wiki/Hotel_Chelsea"},{"name":"Macy's Herald Square","x":127.7,"y":839.2,"lat":40.7508,"lon":-73.989,"fact":"Once billed as the world's largest store.","about":"Macy's Herald Square (originally named the R. H.","wiki":"https://en.wikipedia.org/wiki/Macy%27s_Herald_Square","img":"data:image/jpeg;base64,","credit":"Balou46 CC BY-SA 4.0","file":"https://commons.wikimedia.org/wiki/File:NYC-manhattan-macys.jpg"}],"targets":[{"name":"Katz's Delicatessen","x":1774.2,"y":3523.1,"lat":40.722343,"lon":-73.987353,"cat":"R","fact":"Serving pastrami since 1888.","about":"Katz's Delicatessen, also known as Katz's of New York City, is a Jewish deli at 205 East Houston Street, on the southwest corner of Houston and Ludlow Streets on the Lower East Side of Manhattan in New York City.","wiki":"https://en.wikipedia.org/wiki/Katz%27s_Delicatessen","img":"data:image/jpeg;base64,","credit":"ajay_suresh CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:Katz%27s_Delicatessen_(51623899326).jpg"},{"name":"Joe's Pizza","x":249.7,"y":3331.3,"lat":40.730547,"lon":-74.002063,"cat":"R","fact":"The classic Carmine Street slice since 1975.","about":"Joe's Pizza, also called Famous Joe's Pizza, is a pizzeria located in Greenwich Village, Manhattan, New York City on Carmine Street near Bleecker Street. The restaurant is known for serving a classic New York street-style pizza and has been called a \"Greenwich Village institution\".","wiki":"https://en.wikipedia.org/wiki/Joe%27s_Pizza"},{"name":"Russ & Daughters","x":1699.5,"y":3534.2,"lat":40.722583,"lon":-73.988192,"cat":"R","fact":"An 'appetizing' shop open since 1914.","about":"Russ & Daughters is an appetizing store that opened in 1914. It is located at 179 East Houston Street, on the Lower East Side of Manhattan, New York City.","wiki":"https://en.wikipedia.org/wiki/Russ_%26_Daughters","img":"data:image/jpeg;base64,","credit":"ajay_suresh CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:Russ_%26_Daughters_(51624125108).jpg"},{"name":"Levain Bakery","x":-793.2,"y":-2328.1,"lat":40.779899,"lon":-73.980342,"cat":"R","fact":"Famous for six-ounce cookies.","about":"Levain Bakery, pronounced as (luh-ven), is a retail bakery that opened in 1995 and is located at 167 West 74th Street, on the Upper West Side neighborhood of Manhattan, New York City.","wiki":"https://en.wikipedia.org/wiki/Levain_Bakery","img":"data:image/jpeg;base64,","credit":"Julie Skarratt Public domain","file":"https://commons.wikimedia.org/wiki/File:Storefrontny.jpg"},{"name":"Magnolia Bakery","x":-253.1,"y":2935.0,"lat":40.735888,"lon":-74.005,"cat":"R","fact":"Its cupcakes starred on Sex and the City.","about":"Magnolia Bakery is a chain of bakeries founded in New York City. The first location opened in 1996 at 401 Bleecker Street, on the corner of West 11th Street in the West Village neighborhood of Manhattan.","wiki":"https://en.wikipedia.org/wiki/Magnolia_Bakery","img":"data:image/jpeg;base64,","credit":"Ajay Suresh CC BY 4.0","file":"https://commons.wikimedia.org/wiki/File:Magnolia_Bakery_(55380999079).jpg"},{"name":"Sylvia's","x":313.4,"y":-6530.9,"lat":40.8083,"lon":-73.9447,"cat":"R","fact":"The Queen of Soul Food, open since 1962.","about":"Sylvia's Restaurant of Harlem, often called Sylvia's Soul Food or just Sylvia's, is a soul food restaurant located at 328 Malcolm X Boulevard, between 126th and 127th Streets, in Harlem, Manhattan, New York City.","wiki":"https://en.wikipedia.org/wiki/Sylvia%27s_Restaurant_of_Harlem","img":"data:image/jpeg;base64,","credit":"Ajay Suresh from New York, NY, USA CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:Harlem_-_Sylvia%27s_Restaurant_(48555310372).jpg"},{"name":"Tavern on the Green","x":-175.5,"y":-1696.7,"lat":40.772194,"lon":-73.977565,"cat":"R","fact":"Built in 1870 as a sheepfold for Central Park's sheep.","about":"Tavern on the Green is an American cuisine restaurant in Central Park in Manhattan, New York City, near the intersection of Central Park West and West 66th Street on the Upper West Side. The restaurant, housed in a former sheepfold, has been operated by Jim Caiola and David Salama since 2014.","wiki":"https://en.wikipedia.org/wiki/Tavern_on_the_Green"},{"name":"Nom Wah Tea Parlor","x":1397.0,"y":4728.6,"lat":40.714459,"lon":-73.998197,"cat":"R","fact":"Chinatown's oldest dim sum parlor, opened 1920.","about":"Nom Wah Tea Parlor (Chinese: 南華茶室; Cantonese Yale: Nàahm Wàh Chàhsāt; lit. 'South China Tea House'), opened in 1920, is the oldest continuously running restaurant in the Chinatown of Manhattan in New York City.","wiki":"https://en.wikipedia.org/wiki/Nom_Wah_Tea_Parlor","img":"data:image/jpeg;base64,","credit":"Bagelpigeon CC0","file":"https://commons.wikimedia.org/wiki/File:Nom_Wah_Tea_Parlor_in_New_York_City_Chinatown.jpg"},{"name":"Ferrara Bakery","x":1214.4,"y":4243.3,"lat":40.7191,"lon":-73.9973,"cat":"R","fact":"Little Italy pastry shop since 1892.","about":"Ferrara Bakery and Cafe, established in 1892 by Antonio Ferrara, claims to be America's first espresso bar. It is located in Little Italy, Manhattan, New York City, and offers Italian delicacies.","wiki":"https://en.wikipedia.org/wiki/Ferrara_Bakery_and_Cafe","img":"data:image/jpeg;base64,","credit":"terren in Virginia CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:Front_of_Ferrara_Bakery_and_Cafe.jpg"},{"name":"Veselka","x":1444.8,"y":2867.2,"lat":40.728977,"lon":-73.986998,"cat":"R","fact":"Ukrainian pierogi around the clock since 1954.","about":"Veselka is a Ukrainian restaurant at 144 Second Avenue in the East Village neighborhood of Manhattan in New York City. It was established in 1954 by Wolodymyr Darmochwal (Ukrainian: Володимир Дармохвал) and his wife, Olha Darmochwal (Ukrainian: Ольга Дармохвал), post–World War II Ukrainian refugees.","wiki":"https://en.wikipedia.org/wiki/Veselka","img":"data:image/jpeg;base64,","credit":"ajay_suresh CC BY 4.0","file":"https://commons.wikimedia.org/wiki/File:Veselka_(55380948638).jpg"},{"name":"Lombardi's","x":1205.8,"y":3932.1,"lat":40.7216,"lon":-73.9956,"cat":"R","fact":"Often called America's first pizzeria.","about":"Lombardi's is a pizzeria at 32 Spring Street on the corner of Mott Street in the Nolita neighborhood of Manhattan in New York City.","wiki":"https://en.wikipedia.org/wiki/Lombardi%27s_Pizza","img":"data:image/jpeg;base64,","credit":"Beyond My Ken CC BY-SA 4.0","file":"https://commons.wikimedia.org/wiki/File:Lombardi%27s_Pizza.jpg"},{"name":"Gray's Papaya","x":-802.5,"y":-2130.5,"lat":40.778377,"lon":-73.981575,"cat":"R","fact":"Hot dogs and papaya drinks on the Upper West Side.","wiki":"https://en.wikipedia.org/wiki/Gray%27s_Papaya","img":"data:image/jpeg;base64,","credit":"hu:User:Totya CC BY-SA 3.0","file":"https://commons.wikimedia.org/wiki/File:GraysPapayaMidtown.jpg"},{"name":"Junior's","x":-94.6,"y":25.3,"lat":40.758215,"lon":-73.986627,"cat":"R","fact":"Cheesecake in the heart of the Theater District.","about":"Junior's is a restaurant chain with the original location at 386 Flatbush Avenue Extension at the corner of DeKalb Avenue in Downtown Brooklyn, New York City. Other locations include the Times Square area and the lobby of the Fox Tower in the Foxwoods Resort in  Ledyard, Connecticut.","wiki":"https://en.wikipedia.org/wiki/Junior%27s"},{"name":"Shake Shack Madison Square Park","x":690.5,"y":1715.3,"lat":40.7414,"lon":-73.9882,"cat":"R","fact":"The original Shake Shack started as a hot dog cart.","about":"Shake Shack is an American multinational fast casual restaurant chain based in New York City. It started out as a hot dog cart inside Madison Square Park in 2001, and its popularity steadily grew.","wiki":"https://en.wikipedia.org/wiki/Shake_Shack","img":"data:image/jpeg;base64,","credit":"Beyond My Ken CC BY-SA 4.0","file":"https://commons.wikimedia.org/wiki/File:Shake_Shack_Madison_Square.jpg"},{"name":"Keens Steakhouse","x":320.3,"y":735.9,"lat":40.750773,"lon":-73.986409,"cat":"R","fact":"Its ceiling holds thousands of clay pipes.","about":"Keens Steakhouse (formerly Keen's English Chop House) is a steakhouse restaurant located at 72 West 36th Street (between Fifth Avenue and Sixth Avenue) in the Garment District in Manhattan, New York City.","wiki":"https://en.wikipedia.org/wiki/Keens_Steakhouse","img":"data:image/jpeg;base64,","credit":"ajay_suresh CC BY 4.0","file":"https://commons.wikimedia.org/wiki/File:Keens_Steakhouse_(54821833498).jpg"},{"name":"Balthazar","x":960.0,"y":3934.6,"lat":40.722658,"lon":-73.998164,"cat":"R","fact":"A Paris-style brasserie in SoHo.","about":"Balthazar is a French brasserie restaurant located at 80 Spring Street (between Broadway and Crosby Street) in SoHo in Manhattan, in New York City. It opened on April 21, 1997, and is owned by British-born restaurateur Keith McNally.","wiki":"https://en.wikipedia.org/wiki/Balthazar_(restaurant)","img":"data:image/jpeg;base64,","credit":"Ralph Daily CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:Balthazar_on_Spring_Street.jpg"},{"name":"Minetta Tavern","x":381.6,"y":3314.7,"lat":40.7301,"lon":-74.0006,"cat":"R","fact":"A Greenwich Village tavern dating to 1937.","about":"Minetta Tavern is a restaurant owned by Keith McNally in Greenwich Village. In 2009, Frank Bruni of The New York Times gave the Tavern three stars.","wiki":"https://en.wikipedia.org/wiki/Minetta_Tavern","img":"data:image/jpeg;base64,","credit":"MainlyTwelve CC BY-SA 4.0","file":"https://commons.wikimedia.org/wiki/File:Minetta_Tavern_%E2%80%93_January_2023_%E2%80%93_by_MainlyTwelve.jpg"},{"name":"Delmonico's","x":1016.0,"y":6130.0,"lat":40.705042,"lon":-74.010205,"cat":"R","fact":"Where the Delmonico steak got its name.","about":"Delmonico's is a series of restaurants that have operated in New York City, with the present version located at 56 Beaver Street in the Financial District of Manhattan. The original version opened in 1827 at 23 William Street.","wiki":"https://en.wikipedia.org/wiki/Delmonico%27s","img":"data:image/jpeg;base64,","credit":"Ajay Suresh CC BY 4.0","file":"https://commons.wikimedia.org/wiki/File:Delmonico%27s_-_56_Beaver_Street_(55312935822).jpg"},{"name":"Fraunces Tavern","x":1011.9,"y":6338.7,"lat":40.703409,"lon":-74.011449,"cat":"R","fact":"Washington bid farewell to his officers here in 1783.","about":"Fraunces Tavern is a museum, bar and restaurant in New York City, situated at 54 Pearl Street at the corner of Pearl and Broad Streets in the Financial District of Lower Manhattan. Fraunces Tavern played a prominent role in history before, during, and after the American Revolution.","wiki":"https://en.wikipedia.org/wiki/Fraunces_Tavern","img":"data:image/jpeg;base64,","credit":"Jim.henderson Public domain","file":"https://commons.wikimedia.org/wiki/File:Frauncestavern.JPG"},{"name":"Chelsea Market","x":-777.4,"y":2336.3,"lat":40.742924,"lon":-74.006996,"cat":"R","fact":"The old Nabisco factory where the Oreo was invented.","about":"Chelsea Market is a food hall, shopping mall, office building and television production facility located in the Chelsea neighborhood of the borough of Manhattan, in New York City.","wiki":"https://en.wikipedia.org/wiki/Chelsea_Market","img":"data:image/jpeg;base64,","credit":"Ajay Suresh from New York, NY, USA CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:Chelsea_Market_(49052085186).jpg"},{"name":"Zabar's","x":-1011.5,"y":-2839.4,"lat":40.784902,"lon":-73.979667,"cat":"R","fact":"An Upper West Side food emporium since 1934.","about":"Zabar's ( ZAY-barz) is an appetizing store at 2245 Broadway and 80th Street, on the Upper West Side of Manhattan in New York City, founded by Louis and Lillian Zabar. It is known for its selection of bagels, smoked fish, olives, and cheeses.","wiki":"https://en.wikipedia.org/wiki/Zabar%27s","img":"data:image/jpeg;base64,","credit":"Fuzheado CC BY-SA 4.0","file":"https://commons.wikimedia.org/wiki/File:Zabars-2016-front-wide.jpg"},{"name":"Barney Greengrass","x":-798.6,"y":-3344.5,"lat":40.787965,"lon":-73.974554,"cat":"R","fact":"'The Sturgeon King' since 1908.","about":"Barney Greengrass is a restaurant, deli, and appetizing store at 541 Amsterdam Avenue (between West 86th and 87th Streets) on the Upper West Side of Manhattan, New York City, started in 1908.","wiki":"https://en.wikipedia.org/wiki/Barney_Greengrass"},{"name":"Serendipity 3","x":1312.7,"y":-1208.2,"lat":40.761802,"lon":-73.964938,"cat":"R","fact":"Home of the Frrrozen Hot Chocolate.","about":"Serendipity 3, often written Serendipity III, is a restaurant located at 225 East 60th Street, between Second and Third avenues in New York City, founded by Calvin L Holt, Patch Caradine and Stephen Bruce in 1954.","wiki":"https://en.wikipedia.org/wiki/Serendipity_3","img":"data:image/jpeg;base64,","credit":"Ben W CC BY-SA 2.0","file":"https://commons.wikimedia.org/wiki/File:Entrance_to_Serendipity_3,_the_New_York_City_dessert_restaurant.jpg"},{"name":"Rao's","x":1853.3,"y":-5567.5,"lat":40.793923,"lon":-73.934267,"cat":"R","fact":"Ten tables, nearly impossible to book.","about":"Rao's () is an Italian-American restaurant founded in 1896. It is located at 455 East 114th Street, on the corner of Pleasant Avenue in East Harlem (or Italian Harlem), New York City.","wiki":"https://en.wikipedia.org/wiki/Rao%27s"},{"name":"Dominique Ansel Bakery","x":472.4,"y":3887.3,"lat":40.725171,"lon":-74.00295,"cat":"R","fact":"Birthplace of the Cronut.","about":"Dominique Ansel (born 1978) is a French pastry chef and owner of Dominique Ansel Bakery in New York City. He is the inventor of the Cronut, a croissant-donut hybrid.","wiki":"https://en.wikipedia.org/wiki/Dominique_Ansel","img":"data:image/jpeg;base64,","credit":"Nan Palmero CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:Dominique_Ansel_2014.jpg"},{"name":"Pete's Tavern","x":1062.6,"y":2127.5,"lat":40.736506,"lon":-73.986711,"cat":"R","fact":"Claims to be NYC's oldest continuously operating bar.","about":"Pete's Tavern, located at 129 East 18th Street on the corner of Irving Place in the Gramercy Park neighborhood of Manhattan, New York City, is a pub food restaurant and the oldest continuously operating restaurant and bar in New York City.","wiki":"https://en.wikipedia.org/wiki/Pete%27s_Tavern","img":"data:image/jpeg;base64,","credit":"Dmadeo; cropped by Beyond My Ken (talk) 02:20, 28 April 2011 (UTC) CC BY-SA 3.0","file":"https://commons.wikimedia.org/wiki/File:Petes-tavern-2007_crop.jpg"},{"name":"P.J. Clarke's","x":1221.0,"y":-801.0,"lat":40.758983,"lon":-73.96823,"cat":"R","fact":"A saloon from 1884 that refused to be torn down.","about":"P. J.","wiki":"https://en.wikipedia.org/wiki/P._J._Clarke%27s","img":"data:image/jpeg;base64,","credit":"ajay_suresh CC BY 4.0","file":"https://commons.wikimedia.org/wiki/File:P._J._Clarke%27s_(55273671468).jpg"},{"name":"Mamoun's Falafel","x":386.9,"y":3294.4,"lat":40.730237,"lon":-74.000428,"cat":"R","fact":"Serving falafel on MacDougal since 1971."},{"name":"Red Rooster","x":331.5,"y":-6515.7,"lat":40.8081,"lon":-73.9446,"cat":"R","fact":"Marcus Samuelsson's Harlem restaurant."},{"name":"Metropolitan Museum of Art","x":497.8,"y":-2980.6,"lat":40.7794,"lon":-73.9632,"cat":"M","fact":"More than two million works across 5,000 years.","about":"The Metropolitan Museum of Art, colloquially referred to as the Met, is an encyclopedic art museum in New York City. By floor area, it is the third-largest museum in the world and the largest art museum in the Americas.","wiki":"https://en.wikipedia.org/wiki/Metropolitan_Museum_of_Art","img":"data:image/jpeg;base64,","credit":"Hugo Schneider CC BY-SA 2.0","file":"https://commons.wikimedia.org/wiki/File:Metropolitan_Museum_of_Art_(The_Met)_-_Central_Park,_NYC.jpg"},{"name":"Museum of Modern Art","x":400.4,"y":-651.7,"lat":40.7614,"lon":-73.9776,"cat":"M","fact":"Home of Van Gogh's The Starry Night.","about":"The Museum of Modern Art (MoMA) is an art museum located in Midtown Manhattan, New York City, on 53rd Street between Fifth and Sixth Avenues.","wiki":"https://en.wikipedia.org/wiki/Museum_of_Modern_Art","img":"data:image/jpeg;base64,","credit":"hibino CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:MoMa_NY_USA_1.jpg"},{"name":"Solomon R. Guggenheim Museum","x":614.6,"y":-3500.3,"lat":40.783,"lon":-73.959,"cat":"M","fact":"Frank Lloyd Wright's spiral opened in 1959.","about":"The Solomon R. Guggenheim Museum, often referred to as The Guggenheim, is an art museum at 1071 Fifth Avenue between 88th and 89th Streets on the Upper East Side of Manhattan in New York City.","wiki":"https://en.wikipedia.org/wiki/Solomon_R._Guggenheim_Museum","img":"data:image/jpeg;base64,","credit":"Ajay Suresh from New York, NY, USA CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:Solomon_R._Guggenheim_Museum_(48059131351).jpg"},{"name":"American Museum of Natural History","x":-405.3,"y":-2694.7,"lat":40.781099,"lon":-73.974211,"cat":"M","fact":"Its blue whale model is 94 feet long.","about":"The American Museum of Natural History (AMNH) is a natural history museum on the Upper West Side of Manhattan in New York City.","wiki":"https://en.wikipedia.org/wiki/American_Museum_of_Natural_History","img":"data:image/jpeg;base64,","credit":"Ingfbruno CC BY-SA 3.0","file":"https://commons.wikimedia.org/wiki/File:USA-NYC-American_Museum_of_Natural_History.JPG"},{"name":"Whitney Museum of American Art","x":-744.3,"y":2733.9,"lat":40.739633,"lon":-74.008938,"cat":"M","fact":"Founded by sculptor Gertrude Vanderbilt Whitney.","about":"The Whitney Museum of American Art (known informally as \"The Whitney\") is a modern and contemporary American art museum in the Meatpacking District and West Village neighborhoods of Manhattan in New York City, New York, United States.","wiki":"https://en.wikipedia.org/wiki/Whitney_Museum_of_American_Art"},{"name":"Intrepid Museum","x":-1383.8,"y":-57.0,"lat":40.76452,"lon":-73.999526,"cat":"M","fact":"An aircraft carrier turned museum.","about":"The Intrepid Museum (originally the Intrepid Sea, Air & Space Museum) is a military, aerospace, and history museum in New York City, United States. It is located at Pier 86 at 46th Street, along the Hudson River, in the Hell's Kitchen neighborhood on the West Side of Manhattan.","wiki":"https://en.wikipedia.org/wiki/Intrepid_Museum","img":"data:image/jpeg;base64,","credit":"Ajay Suresh from New York, NY, USA CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:Intrepid_Museum_(49052290092).jpg"},{"name":"New York Public Library","x":542.4,"y":329.5,"lat":40.753014,"lon":-73.981769,"cat":"M","fact":"Guarded by the lions Patience and Fortitude.","about":"The Stephen A. Schwarzman Building (commonly known as the Main Branch, the 42nd Street Library, or just the New York Public Library) is the flagship building in the New York Public Library system in the Midtown neighborhood of Manhattan in New York City.","wiki":"https://en.wikipedia.org/wiki/New_York_Public_Library_Main_Branch","img":"data:image/jpeg;base64,","credit":"ajay_suresh CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:New_York_Public_Library_-_Main_Branch_(51396225599).jpg"},{"name":"9/11 Memorial & Museum","x":485.3,"y":5613.5,"lat":40.711456,"lon":-74.012742,"cat":"M","fact":"Two pools sit in the footprints of the Twin Towers.","about":"The National September 11 Memorial & Museum (also known as the 9/11 Memorial & Museum) is a memorial and museum that are part of the World Trade Center complex, in New York City, created for remembering the September 11, 2001, terrorist attacks which killed 2,977 people, as well as the February 26, 1993, World Trade Center bombing which killed six.","wiki":"https://en.wikipedia.org/wiki/National_September_11_Memorial_%26_Museum","img":"data:image/jpeg;base64,","credit":"Paul Sableman CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:9-11_Memorial_and_Museum_(28815276064).jpg"},{"name":"Tenement Museum","x":1774.2,"y":3983.5,"lat":40.7187,"lon":-73.99,"cat":"M","fact":"Tells immigrant stories from 97 Orchard Street.","about":"The Lower East Side Tenement Museum is a museum and National Historic Site located at 97 and 103 Orchard Street on the Lower East Side of Manhattan in New York City, United States.","wiki":"https://en.wikipedia.org/wiki/Lower_East_Side_Tenement_Museum","img":"data:image/jpeg;base64,","credit":"Fletcher6 CC BY-SA 3.0","file":"https://commons.wikimedia.org/wiki/File:97_Orchard_Street_Front.jpg"},{"name":"The Met Cloisters","x":-1775.9,"y":-12522.3,"lat":40.864868,"lon":-73.931923,"cat":"M","fact":"Built from pieces of medieval European abbeys.","about":"The Cloisters (also known as the Met Cloisters) is a museum in Fort Tryon Park, straddling the neighborhoods of Washington Heights and Inwood, in Upper Manhattan, New York City. The museum specializes in European medieval art and architecture, with a focus on the Romanesque and Gothic periods.","wiki":"https://en.wikipedia.org/wiki/The_Cloisters","img":"data:image/jpeg;base64,","credit":"Christopher Down CC BY 4.0","file":"https://commons.wikimedia.org/wiki/File:The_Met_Cloisters.jpg"},{"name":"The Frick Collection","x":634.8,"y":-2020.2,"lat":40.7712,"lon":-73.9673,"cat":"M","fact":"Old Masters in Henry Clay Frick's mansion.","about":"The Frick Collection (colloquially known as the Frick) is an art museum on the Upper East Side of Manhattan in New York City. It was established in 1935 to preserve the collection of the industrialist Henry Clay Frick.","wiki":"https://en.wikipedia.org/wiki/Frick_Collection","img":"data:image/jpeg;base64,","credit":"CVB CC BY-SA 4.0","file":"https://commons.wikimedia.org/wiki/File:Frick_Collection_New_York_cour.jpg"},{"name":"Neue Galerie","x":617.2,"y":-3286.9,"lat":40.7813,"lon":-73.9602,"cat":"M","fact":"Home of Klimt's 'Woman in Gold'.","about":"The Neue Galerie New York (German for \"New Gallery\") is a museum of early twentieth-century German and Austrian art and design on the Upper East Side of Manhattan in New York City. It is located in the William Starr Miller House at 86th Street and Fifth Avenue.","wiki":"https://en.wikipedia.org/wiki/Neue_Galerie_New_York","img":"data:image/jpeg;base64,","credit":"Neue Galerie New York Public domain","file":"https://commons.wikimedia.org/wiki/File:Neue_Galerie_New_York_Logo.jpg"},{"name":"Cooper Hewitt","x":633.4,"y":-3675.1,"lat":40.7843,"lon":-73.9578,"cat":"M","fact":"The national design museum, in Carnegie's mansion.","about":"Cooper Hewitt, Smithsonian Design Museum is a design museum at the Andrew Carnegie Mansion in Manhattan, New York City, along the Upper East Side's Museum Mile.","wiki":"https://en.wikipedia.org/wiki/Cooper_Hewitt,_Smithsonian_Design_Museum"},{"name":"Museum of the City of New York","x":628.2,"y":-4709.3,"lat":40.792506,"lon":-73.951908,"cat":"M","fact":"Tells the story of the city from 1609 on.","about":"The Museum of the City of New York (MCNY) is a history and art museum in Manhattan, New York City. It was founded by Henry Collins Brown in 1923 to preserve and present the history of New York City and its people.","wiki":"https://en.wikipedia.org/wiki/Museum_of_the_City_of_New_York"},{"name":"Studio Museum in Harlem","x":92.1,"y":-6408.3,"lat":40.8083,"lon":-73.9477,"cat":"M","fact":"Champions artists of African descent.","about":"The Studio Museum in Harlem is an African-American art museum at 144 West 125th Street in the Harlem neighborhood of Manhattan, New York City, United States.","wiki":"https://en.wikipedia.org/wiki/Studio_Museum_in_Harlem"},{"name":"New Museum","x":1369.3,"y":3747.1,"lat":40.722346,"lon":-73.992841,"cat":"M","fact":"Its building looks like a stack of offset boxes.","about":"The New Museum of Contemporary Art is a museum at 235 Bowery, on the Lower East Side of Manhattan in New York City. It was founded in 1977 by Marcia Tucker.","wiki":"https://en.wikipedia.org/wiki/New_Museum"},{"name":"The Morgan Library & Museum","x":765.5,"y":679.2,"lat":40.749268,"lon":-73.981465,"cat":"M","fact":"J.P. Morgan's private library, with three Gutenberg Bibles.","about":"The Morgan Library & Museum (formerly the Pierpont Morgan Library; colloquially the Morgan) is a museum and research library in New York City, New York, United States. Completed in 1906 as the private library of the banker J.","wiki":"https://en.wikipedia.org/wiki/Morgan_Library_%26_Museum","img":"data:image/jpeg;base64,","credit":"Photograph by Mike Peel (www.mikepeel.net). CC BY-SA 4.0","file":"https://commons.wikimedia.org/wiki/File:Morgan_Library_%26_Museum,_New_York_2017_02.jpg"},{"name":"New-York Historical Society","x":-312.2,"y":-2517.2,"lat":40.779286,"lon":-73.974265,"cat":"M","fact":"New York's oldest museum, founded 1804.","about":"The New York Historical (known as the New-York Historical Society until 2024) is an American history museum and library on the Upper West Side of Manhattan in New York City. The society was founded in 1804 as New York's first museum.","wiki":"https://en.wikipedia.org/wiki/New_York_Historical","img":"data:image/jpeg;base64,","credit":"Ajay Suresh from New York, NY, USA CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:New_York_Historical_Society_(48269593386).jpg"},{"name":"Hispanic Society Museum","x":-1190.0,"y":-8895.2,"lat":40.8336,"lon":-73.9467,"cat":"M","fact":"Holds works by Goya, Velazquez, and Sorolla.","about":"The Hispanic Society of America, now renamed the Hispanic Society Museum and Library (HSM&L), operates a museum and reference library for the study of the arts and cultures of Spain and Portugal and their former colonies in Latin America, the Spanish East Indies, and Portuguese India.","wiki":"https://en.wikipedia.org/wiki/Hispanic_Society_of_America","img":"data:image/jpeg;base64,","credit":"Asaavedra32 CC BY-SA 3.0","file":"https://commons.wikimedia.org/wiki/File:HispanicSocietyofAmerica.jpg"},{"name":"Museum of Jewish Heritage","x":317.6,"y":6362.9,"lat":40.706262,"lon":-74.018789,"cat":"M","fact":"A living memorial to the Holocaust.","about":"The Museum of Jewish Heritage, located on Edmond J. Safra Plaza in the Battery Park City neighborhood of Manhattan, New York City, is a historical museum and a memorial to those murdered in The Holocaust.","wiki":"https://en.wikipedia.org/wiki/Museum_of_Jewish_Heritage","img":"data:image/jpeg;base64,","credit":"Gryffindor CC BY-SA 3.0","file":"https://commons.wikimedia.org/wiki/File:Museum_of_Jewish_Heritage_005.JPG"},{"name":"Merchant's House Museum","x":1121.3,"y":3213.3,"lat":40.727658,"lon":-73.992344,"cat":"M","fact":"A family home frozen in the 1800s, said to be haunted.","about":"The Merchant's House Museum, also known as the Old Merchant's House and the Seabury Tredwell House, is a historic house museum at 29 East Fourth Street in the NoHo neighborhood of Manhattan in New York City.","wiki":"https://en.wikipedia.org/wiki/Merchant%27s_House_Museum","img":"data:image/jpeg;base64,","credit":"Ajay Suresh from New York, NY, USA CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:Merchant%27s_House_Museum_(48072654706).jpg"},{"name":"The Jewish Museum","x":619.5,"y":-3807.0,"lat":40.785405,"lon":-73.957186,"cat":"M","fact":"Housed in the Warburg mansion on Fifth Avenue.","about":"The Jewish Museum is an art museum housed at 1109 Fifth Avenue, in the Felix M. Warburg House, along the Museum Mile on the Upper East Side of Manhattan, New York City.","wiki":"https://en.wikipedia.org/wiki/Jewish_Museum_(Manhattan)","img":"data:image/jpeg;base64,","credit":"Ajay Suresh from New York, NY, USA CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:Jewish_Museum_(48059132236).jpg"},{"name":"Strand Bookstore","x":923.6,"y":2612.4,"lat":40.73328,"lon":-73.99094,"cat":"M","fact":"Famous for its '18 miles of books'.","about":"The Strand Bookstore is an independent bookstore located at 828 Broadway, at the corner of East 12th Street in the East Village neighborhood of Manhattan, New York City, two blocks south of Union Square.","wiki":"https://en.wikipedia.org/wiki/Strand_Bookstore"},{"name":"Jefferson Market Library","x":248.7,"y":2822.3,"lat":40.734578,"lon":-73.999147,"cat":"M","fact":"A former courthouse turned library.","about":"The Jefferson Market Branch of the New York Public Library, once known as the Jefferson Market Courthouse, is a National Historic Landmark located at 425 Avenue of the Americas (Sixth Avenue), on the southwest corner of West 10th Street, in Greenwich Village, Manhattan, New York City, on a triangular plot formed by Greenwich Avenue and West 10th Street.","wiki":"https://en.wikipedia.org/wiki/Jefferson_Market_Library","img":"data:image/jpeg;base64,","credit":"GuardianKC CC BY-SA 4.0","file":"https://commons.wikimedia.org/wiki/File:Jefferson_Market_Library_at_sunset.jpg"},{"name":"Central Park Zoo","x":497.9,"y":-1502.1,"lat":40.767702,"lon":-73.971699,"cat":"P","fact":"Its sea lion feedings draw crowds daily.","about":"The Central Park Zoo is a 6.5-acre (2.6 ha) zoo located at the southeast corner of Central Park in New York City. It is part of an integrated system of four zoos and one aquarium managed by the Wildlife Conservation Society (WCS).","wiki":"https://en.wikipedia.org/wiki/Central_Park_Zoo","img":"data:image/jpeg;base64,","credit":"Tim Rodenberg CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:Central_Park_Zoo_area.jpg"},{"name":"The High Line","x":-822.5,"y":1725.8,"lat":40.747953,"lon":-74.003954,"cat":"P","fact":"A park built on an old freight rail line.","about":"The High Line is a 1.45-mile-long (2.33 km) elevated linear park, greenway, and rail trail created on a former New York Central Railroad spur on the West Side of Manhattan in New York City.","wiki":"https://en.wikipedia.org/wiki/High_Line","img":"data:image/jpeg;base64,","credit":"Dansnguyen CC0","file":"https://commons.wikimedia.org/wiki/File:High_Line_Park,_Section_1a.jpg"},{"name":"Little Island","x":-994.6,"y":2572.9,"lat":40.742005,"lon":-74.01061,"cat":"P","fact":"A park floating on 132 tulip-shaped concrete pots.","about":"Little Island at Pier 55 (stylized as Little Island @Pier55) is an artificial island and a public park within Hudson River Park, just off the western coast of Manhattan in New York City.","wiki":"https://en.wikipedia.org/wiki/Little_Island_at_Pier_55","img":"data:image/jpeg;base64,","credit":"Praneeth Thalla CC BY-SA 4.0","file":"https://commons.wikimedia.org/wiki/File:Little_Island_at_Pier_55.jpg"},{"name":"Bryant Park","x":372.4,"y":330.6,"lat":40.753751,"lon":-73.983538,"cat":"P","fact":"Winter brings a free ice rink.","about":"Bryant Park is a 9.6-acre (3.9 ha), privately managed public park in the New York City borough of Manhattan. It is located between Fifth Avenue and Avenue of the Americas (Sixth Avenue) and between 40th and 42nd Streets in Midtown Manhattan.","wiki":"https://en.wikipedia.org/wiki/Bryant_Park","img":"data:image/jpeg;base64,","credit":"Jean-Christophe BENOIST CC BY 3.0","file":"https://commons.wikimedia.org/wiki/File:New-York_-_Bryant_Park.jpg"},{"name":"The Battery","x":944.6,"y":6719.8,"lat":40.700688,"lon":-74.014338,"cat":"P","fact":"The southern tip of Manhattan.","about":"The Battery, formerly known as Battery Park, is a 25-acre (10 ha) public park located at the southern tip of Manhattan Island in New York City facing New York Harbor.","wiki":"https://en.wikipedia.org/wiki/The_Battery_(Manhattan)","img":"data:image/jpeg;base64,","credit":"Gryffindor CC BY-SA 3.0","file":"https://commons.wikimedia.org/wiki/File:Battery_Park.JPG"},{"name":"Madison Square Park","x":672.5,"y":1625.8,"lat":40.742187,"lon":-73.987872,"cat":"P","fact":"Once home to the Statue of Liberty's torch.","about":"Madison Square is a public square formed by the intersection of Fifth Avenue and Broadway at 23rd Street in the New York City borough of Manhattan. The square was named for Founding Father James Madison, the fourth president of the United States.","wiki":"https://en.wikipedia.org/wiki/Madison_Square_and_Madison_Square_Park","img":"data:image/jpeg;base64,","credit":"alq666 CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:Madison_Square_Park_from_Above_at_Night_New_York_City.jpg"},{"name":"Tompkins Square Park","x":1970.8,"y":2892.2,"lat":40.726472,"lon":-73.981687,"cat":"P","fact":"Birthplace of the Hare Krishna movement in the US.","about":"Tompkins Square Park is a 10.5-acre (4.2 ha) public park in the Alphabet City portion of East Village, Manhattan, New York City. The square-shaped park, bounded on the north by East 10th Street, on the east by Avenue B, on the south by East 7th Street, and on the west by Avenue A, is abutted by St.","wiki":"https://en.wikipedia.org/wiki/Tompkins_Square_Park","img":"data:image/jpeg;base64,","credit":"David Shankbone CC BY-SA 3.0","file":"https://commons.wikimedia.org/wiki/File:Tompkins_Square_Park.JPG"},{"name":"Fort Tryon Park","x":-1500.7,"y":-12179.9,"lat":40.860952,"lon":-73.931037,"cat":"P","fact":"Designed by the Olmsted Brothers, given by Rockefeller.","about":"Fort Tryon Park is a public park located in the Washington Heights and Inwood neighborhoods of the borough of Manhattan in New York City. The 67-acre (27 ha) park is situated on a ridge in Upper Manhattan, close to the Hudson River to the west.","wiki":"https://en.wikipedia.org/wiki/Fort_Tryon_Park","img":"data:image/jpeg;base64,","credit":"Beyond My Ken CC BY-SA 4.0","file":"https://commons.wikimedia.org/wiki/File:2013_Fort_Tryon_Park_main_entrance_sign_at_Margaret_Corbin_Circle_in_snow.jpg"},{"name":"Inwood Hill Park","x":-1687.1,"y":-13505.8,"lat":40.87226,"lon":-73.925348,"cat":"P","fact":"Home to Manhattan's last natural forest.","about":"Inwood Hill Park is a 196 acres (79 ha) public park in the Inwood neighborhood of Manhattan, New York City, operated by the New York City Department of Parks and Recreation.","wiki":"https://en.wikipedia.org/wiki/Inwood_Hill_Park","img":"data:image/jpeg;base64,","credit":"The rakish fellow CC BY-SA 3.0","file":"https://commons.wikimedia.org/wiki/File:Native_Caves.jpg"},{"name":"Marcus Garvey Park","x":637.0,"y":-6242.7,"lat":40.8046,"lon":-73.943,"cat":"P","fact":"Its fire watchtower dates to 1857.","about":"Marcus Garvey Park (formerly and also named Mount Morris Park) is a 20.16-acre (81,600 m2) park on the border between the Harlem and East Harlem neighborhoods of Manhattan, New York City.","wiki":"https://en.wikipedia.org/wiki/Marcus_Garvey_Park","img":"data:image/jpeg;base64,","credit":"Momos Public domain","file":"https://commons.wikimedia.org/wiki/File:Marcus_Garvey_Memorial_Park.jpg"},{"name":"Morningside Park","x":-551.5,"y":-5767.6,"lat":40.806053,"lon":-73.95806,"cat":"P","fact":"A cliffside park designed by Olmsted and Vaux.","about":"Morningside Park is a 30-acre (12-hectare) public park in Upper Manhattan in New York City, New York, United States. The park is bounded by 110th Street to the south, 123rd Street to the north, Morningside Avenue to the east, and Morningside Drive to the west.","wiki":"https://en.wikipedia.org/wiki/Morningside_Park_(Manhattan)","img":"data:image/jpeg;base64,","credit":"Momos CC BY-SA 3.0","file":"https://commons.wikimedia.org/wiki/File:Morningside_Park.jpg"},{"name":"Sheep Meadow","x":43.5,"y":-1734.0,"lat":40.771529,"lon":-73.975079,"cat":"P","fact":"Sheep grazed here until 1934.","about":"Sheep Meadow is a 15-acre (61,000 m2) meadow near the southwestern section of Central Park, between West 66th and 69th Streets in Manhattan, New York City.","wiki":"https://en.wikipedia.org/wiki/Sheep_Meadow","img":"data:image/jpeg;base64,","credit":"Public domain","file":"https://commons.wikimedia.org/wiki/File:Sheep_Meadow,_Central_Park,_New_York_in_April_2004.jpg"},{"name":"Conservatory Garden","x":537.8,"y":-4807.2,"lat":40.793677,"lon":-73.952283,"cat":"P","fact":"Central Park's only formal garden.","about":"The Conservatory Garden is a formal garden near the northeastern corner of Central Park in Upper Manhattan, New York City. Comprising 6 acres (24,000 m2), it is the only formal garden in Central Park.","wiki":"https://en.wikipedia.org/wiki/Conservatory_Garden","img":"data:image/jpeg;base64,","credit":"Summ CC BY-SA 3.0","file":"https://commons.wikimedia.org/wiki/File:Central_Park_23.jpg"},{"name":"Seward Park","x":2044.3,"y":4322.9,"lat":40.71483,"lon":-73.98915,"cat":"P","fact":"Home to one of the first municipal playgrounds in the US.","about":"Seward Park is a public park and playground on the Lower East Side of Manhattan, New York City. Located north of East Broadway and east of Essex Street, it is 3.046 acres (12,330 m2) in size and is the first municipally built playground in the United States.\n\n","wiki":"https://en.wikipedia.org/wiki/Seward_Park_(Manhattan)","img":"data:image/jpeg;base64,","credit":"This photo was taken by participant/team Sheila as part of the Commons:Wikipedia CC BY-SA 3.0","file":"https://commons.wikimedia.org/wiki/File:Seward_Park,_NYC_(WTM_sheila_0017).jpg"},{"name":"Columbus Park","x":1226.2,"y":4743.2,"lat":40.715093,"lon":-74.000053,"cat":"P","fact":"Chinatown's park, once the notorious Five Points.","about":"Columbus Park formerly known as Mulberry Bend Park, Five Points Park and Paradise Park, is a public park in Chinatown, Manhattan, in New York City that was built in 1897.","wiki":"https://en.wikipedia.org/wiki/Columbus_Park_(Manhattan)","img":"data:image/jpeg;base64,","credit":"Daniel Schwen CC BY-SA 4.0","file":"https://commons.wikimedia.org/wiki/File:Xiangqi_in_Columbus_Park.jpg"},{"name":"Stuyvesant Square","x":1415.6,"y":2292.8,"lat":40.73365,"lon":-73.984,"cat":"P","fact":"Land donated by Peter Stuyvesant's descendant.","about":"Stuyvesant Square is the name of both a park and its surrounding neighborhood in the New York City borough of Manhattan. The park is located between 15th Street, 17th Street, Rutherford Place, and Nathan D.","wiki":"https://en.wikipedia.org/wiki/Stuyvesant_Square","img":"data:image/jpeg;base64,","credit":"PSPazW CC BY-SA 4.0","file":"https://commons.wikimedia.org/wiki/File:Stuyvesant_Square_Park.jpg"},{"name":"St. Nicholas Park","x":-297.1,"y":-7127.8,"lat":40.8157,"lon":-73.9476,"cat":"P","fact":"A steep park below City College.","about":"St. Nicholas Park is a public park in Manhattan, New York City, between the neighborhoods of Harlem, Hamilton Heights and Manhattanville.","wiki":"https://en.wikipedia.org/wiki/St._Nicholas_Park","img":"data:image/jpeg;base64,","credit":"Jim.henderson Public domain","file":"https://commons.wikimedia.org/wiki/File:St_Nicholas_Park_135_jeh.JPG"},{"name":"Highbridge Water Tower","x":-516.4,"y":-10393.4,"lat":40.8425,"lon":-73.9311,"cat":"P","fact":"Once held water from the Croton Aqueduct."},{"name":"Paley Park","x":643.3,"y":-652.8,"lat":40.760344,"lon":-73.975075,"cat":"P","fact":"A tiny pocket park with a 20-foot waterfall.","about":"Paley Park is a pocket park located at 3 East 53rd Street between Madison and Fifth Avenues in Midtown Manhattan, New York City, on the former site of the Stork Club. Designed by the landscape architectural firm of Zion Breen Richardson Associates, it opened May 23, 1967.","wiki":"https://en.wikipedia.org/wiki/Paley_Park","img":"data:image/jpeg;base64,","credit":"Jim.henderson at en.wikipedia Public domain","file":"https://commons.wikimedia.org/wiki/File:Paley_Park_jeh.jpg"},{"name":"Rockefeller Park","x":-52.1,"y":5210.7,"lat":40.717,"lon":-74.016,"cat":"P","fact":"Battery Park City's riverside lawn.","about":"Rockefeller Park is a city park named in honor of oil magnate John D. Rockefeller Sr., located in Cleveland, Ohio.","wiki":"https://en.wikipedia.org/wiki/Rockefeller_Park","img":"data:image/jpeg;base64,","credit":"Martin Linsey Public domain","file":"https://commons.wikimedia.org/wiki/File:Rockefeller_Park_bridge.jpg"},{"name":"The Great Lawn","x":145.3,"y":-3029.7,"lat":40.781334,"lon":-73.966574,"cat":"P","fact":"Built over the filled-in old reservoir.","about":"The Great Lawn and Turtle Pond are two connected features of Central Park in Manhattan, New York City, United States. The lawn and pond are located on the site of a former reservoir for the Croton Aqueduct system which was infilled during the early 20th century.","wiki":"https://en.wikipedia.org/wiki/Great_Lawn_and_Turtle_Pond","img":"data:image/jpeg;base64,","credit":"Daniel Schwen CC BY-SA 4.0","file":"https://commons.wikimedia.org/wiki/File:NYC_Turtlepond.jpg"},{"name":"Sara D. Roosevelt Park","x":1533.0,"y":4000.0,"lat":40.719628,"lon":-73.992597,"cat":"P","fact":"A long, narrow park on the Lower East Side.","about":"Sara Delano Roosevelt Park is a 7.8-acre (3.2 ha) park on the Lower East Side of the New York City borough of Manhattan.","wiki":"https://en.wikipedia.org/wiki/Sara_D._Roosevelt_Park","img":"data:image/jpeg;base64,","credit":"This photo was taken by participant/team Team Dustizeff as part of the Commons:W CC BY-SA 3.0","file":"https://commons.wikimedia.org/wiki/File:WSTM_Team_Dustizeff_0073.jpg"},{"name":"Alice in Wonderland Statue","x":468.8,"y":-2459.0,"lat":40.7754,"lon":-73.9665,"cat":"L","fact":"Kids are encouraged to climb it.","about":"The Alice in Wonderland is a sculpture located at Central Park in Manhattan, New York City, U.S. It is approximately at 74th Street, on the north side of Conservatory Water.","wiki":"https://en.wikipedia.org/wiki/Alice_in_Wonderland_(sculpture)","img":"data:image/jpeg;base64,","credit":"atp tyreseus / Jere Keys from San Francisco, USA Public domain","file":"https://commons.wikimedia.org/wiki/File:Alice_in_Wonderland_statue_in_Central_Park.jpg"},{"name":"Fearless Girl","x":877.1,"y":5982.7,"lat":40.706817,"lon":-74.0108,"cat":"L","fact":"She now stares down the New York Stock Exchange.","about":"Fearless Girl is a bronze sculpture by Kristen Visbal of a 4-foot-high (1.2 m) girl standing in a self-confident pose. It is located in New York City on Broad Street across from the New York Stock Exchange Building in the Financial District of Manhattan.","wiki":"https://en.wikipedia.org/wiki/Fearless_Girl"},{"name":"Cleopatra's Needle","x":323.1,"y":-2913.6,"lat":40.779636,"lon":-73.965396,"cat":"L","fact":"An Egyptian obelisk about 3,500 years old.","about":"Cleopatra's Needle in New York City is one of a pair of obelisks, together named Cleopatra's Needles, that were moved from the ruins of the Caesareum of Alexandria, Ancient Egypt, in the 19th century.","wiki":"https://en.wikipedia.org/wiki/Cleopatra%27s_Needle_(New_York_City)","img":"data:image/jpeg;base64,","credit":"King of Hearts CC BY-SA 4.0","file":"https://commons.wikimedia.org/wiki/File:Central_Park_New_York_May_2017_004.jpg"},{"name":"St. Paul's Chapel","x":762.2,"y":5479.7,"lat":40.7113,"lon":-74.0091,"cat":"L","fact":"Manhattan's oldest surviving church, from 1766.","about":"St. Paul's Chapel is a chapel building of Trinity Church, an Episcopal parish, at 209 Broadway, between Fulton Street and Vesey Street, in Lower Manhattan, New York City.","wiki":"https://en.wikipedia.org/wiki/St._Paul%27s_Chapel","img":"data:image/jpeg;base64,","credit":"ajay_suresh CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:St._Paul%27s_Chapel_-_NYC_(51522449420).jpg"},{"name":"Woolworth Building","x":756.7,"y":5336.8,"lat":40.712455,"lon":-74.008335,"cat":"L","fact":"Nicknamed the 'Cathedral of Commerce'.","about":"The Woolworth Building is a 792-foot-tall (241 m) residential building and early skyscraper at 233 Broadway in the Tribeca neighborhood of Lower Manhattan in New York City, United States. Designed by Cass Gilbert in the Neo-Gothic style, the Woolworth Building was originally an office skyscraper.","wiki":"https://en.wikipedia.org/wiki/Woolworth_Building"},{"name":"African Burial Ground","x":942.7,"y":4987.9,"lat":40.7144,"lon":-74.0044,"cat":"L","fact":"Resting place of about 15,000 free and enslaved Africans.","about":"African Burial Ground National Monument is a monument at Duane Street and African Burial Ground Way (Elk Street) in the Civic Center section of Lower Manhattan, New York City. Its main building is the Ted Weiss Federal Building at 290 Broadway.","wiki":"https://en.wikipedia.org/wiki/African_Burial_Ground_National_Monument","img":"data:image/jpeg;base64,","credit":"Dmadeo CC BY-SA 3.0","file":"https://commons.wikimedia.org/wiki/File:African_Burial_Ground.jpg"},{"name":"Irish Hunger Memorial","x":7.0,"y":5412.8,"lat":40.715142,"lon":-74.016548,"cat":"L","fact":"A real Irish cottage on a slice of Irish landscape.","about":"The Irish Hunger Memorial (Irish: Cuimhneachán Ghorta Mhóir na hÉireann) is a 0.5-acre (0.20 ha) park at the corner of Vesey Street and North End Avenue in the Battery Park City neighborhood of Manhattan in New York City.","wiki":"https://en.wikipedia.org/wiki/Irish_Hunger_Memorial","img":"data:image/jpeg;base64,","credit":"David Shankbone at en.wikipedia CC BY 2.5","file":"https://commons.wikimedia.org/wiki/File:HungerMemorialNumber6.JPG"},{"name":"Duke Ellington Memorial","x":581.3,"y":-5239.2,"lat":40.796904,"lon":-73.949347,"cat":"L","fact":"Duke stands beside his piano on columns held by nine muses.","about":"The Duke Ellington Memorial by Robert Graham is installed at Duke Ellington Circle in Manhattan, New York City, New York. The monument depicts Duke Ellington at a piano, supported by three columns depicting three caryatids each, known as his nine muses.","wiki":"https://en.wikipedia.org/wiki/Duke_Ellington_Memorial","img":"data:image/jpeg;base64,","credit":"Jim.henderson CC0","file":"https://commons.wikimedia.org/wiki/File:Marathon_thunder_Ellington_Circle_jeh.jpg"},{"name":"LOVE Sculpture","x":290.5,"y":-780.3,"lat":40.7629,"lon":-73.978,"cat":"L","fact":"Robert Indiana's famous tilted O."},{"name":"Tiffany & Co. Fifth Avenue","x":603.6,"y":-928.6,"lat":40.7627,"lon":-73.9739,"cat":"L","fact":"Where Holly Golightly had breakfast.","about":"The Tiffany and Company Building, also known as the Tiffany Building and 401 Fifth Avenue, is an eight-story commercial building at Fifth Avenue and 37th Street in the Midtown Manhattan neighborhood of New York City, New York, United States.","wiki":"https://en.wikipedia.org/wiki/Tiffany_and_Company_Building","img":"data:image/jpeg;base64,","credit":"ajay_suresh CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:Tiffany_and_Company_Building_(51878871095).jpg"},{"name":"The Ansonia","x":-948.4,"y":-2274.1,"lat":40.780153,"lon":-73.982262,"cat":"L","fact":"Once kept a small farm on its roof.","about":"The Ansonia (formerly the Ansonia Hotel) is a condominium building at 2109 Broadway, between 73rd and 74th Streets, on the Upper West Side of Manhattan in New York City, New York, United States. The 17-story structure was designed by French architect Paul Emile Duboy in the Beaux-Arts style.","wiki":"https://en.wikipedia.org/wiki/The_Ansonia","img":"data:image/jpeg;base64,","credit":"Epicgenius CC BY-SA 4.0","file":"https://commons.wikimedia.org/wiki/File:Broadway_Upper_West_Side_Mar_2023_36_(cropped).jpg"},{"name":"Cooper Union Foundation Building","x":1172.7,"y":3002.6,"lat":40.7291,"lon":-73.9906,"cat":"L","fact":"Lincoln gave a career-making speech here in 1860.","about":"The Cooper Union for the Advancement of Science and Art, commonly known as Cooper Union, is a private college on Cooper Square in Manhattan, New York City. Peter Cooper founded the institution in 1859 after learning about the government-supported École Polytechnique in France.","wiki":"https://en.wikipedia.org/wiki/Cooper_Union"},{"name":"Temple Emanu-El","x":636.9,"y":-1619.3,"lat":40.768019,"lon":-73.969583,"cat":"L","fact":"One of the largest synagogues in the world.","about":"Congregation Emanu-El of New York is the oldest Reform Jewish congregation in New York City. It has served as a flagship congregation in the Reform branch of Judaism since its founding in 1845.","wiki":"https://en.wikipedia.org/wiki/Congregation_Emanu-El_of_New_York","img":"data:image/jpeg;base64,","credit":"Jim.henderson Public domain","file":"https://commons.wikimedia.org/wiki/File:Emanu-elNYjeh.JPG"},{"name":"Federal Hall","x":882.7,"y":5905.9,"lat":40.7074,"lon":-74.0103,"cat":"L","fact":"Where Washington took the oath as first President.","about":"Federal Hall was the first capitol building of the United States established under the Constitution.","wiki":"https://en.wikipedia.org/wiki/Federal_Hall","img":"data:image/jpeg;base64,","credit":"Ajay Suresh from New York, NY, USA CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:Federal_Hall_(48126566178).jpg"},{"name":"Castle Clinton","x":616.6,"y":6551.3,"lat":40.703461,"lon":-74.016771,"cat":"L","fact":"A fort that became America's first immigration station.","about":"Castle Clinton (also known as Fort Clinton and Castle Garden) is a restored circular sandstone fort within Battery Park at the southern end of Manhattan in New York City, United States. Built from 1808 to 1811, it was the first American immigration station, predating Ellis Island.","wiki":"https://en.wikipedia.org/wiki/Castle_Clinton","img":"data:image/jpeg;base64,","credit":"Unknown authorUnknown author Public domain","file":"https://commons.wikimedia.org/wiki/File:Habs_castle_clinton.jpg"},{"name":"Sherman Monument","x":578.9,"y":-1129.8,"lat":40.7644,"lon":-73.973,"cat":"L","fact":"A gilded general led by the figure of Victory."},{"name":"Trinity Church","x":706.3,"y":5920.8,"lat":40.708055,"lon":-74.012216,"cat":"L","fact":"Alexander Hamilton is buried in its churchyard.","about":"Trinity Church is a historic parish in the Episcopal Diocese of New York. The church is located at 89 Broadway opposite Wall Street, in the Financial District of Lower Manhattan in New York City.","wiki":"https://en.wikipedia.org/wiki/Trinity_Church_(Manhattan)"},{"name":"Bow Bridge","x":60.8,"y":-2278.2,"lat":40.775759,"lon":-73.971771,"cat":"L","fact":"Central Park's most-filmed bridge.","wiki":"https://en.wikipedia.org/wiki/Bow_Bridge"},{"name":"Soldiers' and Sailors' Monument","x":-1342.5,"y":-3565.1,"lat":40.792096,"lon":-73.978927,"cat":"L","fact":"A marble temple honoring Union soldiers.","about":"The Soldiers' and Sailors' Memorial Monument is located in Riverside Park, at the intersection of 89th Street and Riverside Drive, on the Upper West Side of Manhattan in New York City. It commemorates Union Army soldiers and sailors who served in the American Civil War.","wiki":"https://en.wikipedia.org/wiki/Soldiers%27_and_Sailors%27_Monument_(Manhattan)","img":"data:image/jpeg;base64,","credit":"Beyond My Ken CC BY-SA 4.0","file":"https://commons.wikimedia.org/wiki/File:Soldiers%27_and_Sailers%27_Monument_Manhattan_full_site_at_dusk.jpg"},{"name":"Eldridge Street Synagogue","x":1723.1,"y":4517.4,"lat":40.7147,"lon":-73.9936,"cat":"L","fact":"One of the first great synagogues built by Eastern European Jews in the US.","about":"The Eldridge Street Synagogue is an Orthodox Jewish synagogue at 12–16 Eldridge Street in the Chinatown and Lower East Side neighborhoods of Manhattan in New York City. Built in 1887 for Congregation Kahal Adath Jeshurun, the synagogue is one of the first erected in the U.S. by Eastern European Jews.","wiki":"https://en.wikipedia.org/wiki/Eldridge_Street_Synagogue","img":"data:image/jpeg;base64,","credit":"ajay_suresh CC BY 2.0","file":"https://commons.wikimedia.org/wiki/File:Museum_at_Eldridge_Street_(52302295706).jpg"}]};
